20	/**
21	 * Build a CSS-styled credential badge `<span>` for a repository.
22	 *
23	 * Replaces the previous emoji-based approach (`🔑` / `—`) with a CSS-styled
24	 * element that renders consistently across platforms and is accessible via
25	 * `aria-label`.
26	 *
27	 * The returned element always carries the base `.credential-badge` class plus
28	 * one of:
29	 *   - `.credential-badge--set`  — a credential is configured.
30	 *   - `.credential-badge--none` — no credential is configured.
31	 *
32	 * @param {string|null|undefined} credentialId - The credential ID, or null/undefined when absent.
33	 * @returns {HTMLSpanElement}
34	 *
35	 * @example
36	 * // Credential set
37	 * const badge = buildCredentialBadge('my-cred-id');
38	 * // badge.classList → ['credential-badge', 'credential-badge--set']
39	 *
40	 * @example
41	 * // No credential
42	 * const badge = buildCredentialBadge(null);
43	 * // badge.classList → ['credential-badge', 'credential-badge--none']
44	 */
45	export function buildCredentialBadge(credentialId) {
46	    const span = document.createElement('span');
47	    if (credentialId) {
48	        span.className   = 'credential-badge credential-badge--set';
49	        span.title       = `Credential: ${credentialId}`;
50	        span.textContent = '✓';
51	        span.setAttribute('aria-label', 'Credential configured');
52	    } else {
53	        span.className   = 'credential-badge credential-badge--none';
54	        span.title       = 'No credential configured';
55	        span.textContent = '—';
56	        span.setAttribute('aria-label', 'No credential configured');
57	    }
58	    return span;
59	}

